export const LAND_RINGS: number[][][] = COASTLINE.split(";").map((ring) => {
  let x = 0, y = 0;
  const values = ring.split(",");
  const points: number[][] = [];
  for (let i = 0; i < values.length; i += 2) {
    x += parseInt(values[i], 36); y += parseInt(values[i + 1], 36);
    points.push([x / 10000, y / 10000]);
  }
  return points;
});
